select

from product
/* 只查询上架的商品 */

    /* 自动添加WHERE关键字，只有在内部有条件的时候才会添加 */
    /* 只查询上架的商品 */
    status = 1
    /* 关键词的模糊搜索 ：同时匹配商品名称和描述信息 */
    /* test的表达式决定是否包含内部SQL，当keyword不为空的时候，才包含模糊搜索 */

        and (
        name like concat('%', #{request.keyword}, '%')
        or
        description like concat('%', #{request.keyword}, '%')
        )

    /* 筛选 */
    /* 分类筛选 */

        and category_id = #{request.categoryId}

    /* 价格筛选 */

        and price >= #{request.minPrice}


        and price <= #{request.maxPrice}


/* 排序 */


        /* 按照价格排序 */


                order by price asc


                order by price desc


        , id desc



        /* 按照库存排序 */


                order by stock asc


                order by stock desc


        , id desc


        /* 按照商品名排序 */


                order by name asc


                order by name desc


        , id desc


        /* 按照更新时间排序 */
        order by update_time desc, id desc



limit #{request.offset}, #{request.normalizedPageSize}

